window.ECBA_QUESTION_BANK=window.ECBA_QUESTION_BANK||[];window.ECBA_QUESTION_BANK.push(...[{"id":"q1018","domains":[4],"level":3,"tag":"Change","q":"A bank has agreed on its desired future state but lacks a safe way to transition its branches without service interruptions. Which concept is the main focus of defining transition steps and the approach?","opts":["Stakeholder","Change","Value","Need"],"answer":[1],"why":["Stakeholders are those related to the change, need, or solution.","Correct: the transition approach is part of planning the Change from current to future state.","Value concerns usefulness or benefit to stakeholders.","The need explains why change is required."],"ref":"BABOK Guide v3 §6.4 Define Change Strategy, printed pp. 124–131","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1019","domains":[4],"level":4,"tag":"Change","q":"A manufacturer’s new safety law requires a revised inspection process. Which statements correctly distinguish the change from its surrounding concepts?","opts":["The new law is a context factor influencing the work","The revised inspection process is part of the solution","The need is the transformation itself","The transformation to comply with the law is the change"],"answer":[0,1,3],"why":["Correct: regulation is part of the context that influences the change.","Correct: the revised process is one way to satisfy the need.","The Need is the problem or opportunity to address, not the transformation.","Correct: the transformation from current practice is the change."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §6.1 Analyze Current State, pp. 103–110","multi":true,"sourceSet":"ecba-set-26.html"},{"id":"q1020","domains":[4],"level":5,"tag":"Change","q":"A company plans a phased migration to a new order system. Pilot results reveal a serious data issue, so leaders revise the rollout sequence and add a conversion step. Which interpretation best fits the BACCM?","opts":["The discovery turns the need into a solution","The revised sequence is value, while the data issue is the change","The change remains the transformation; its strategy can be adjusted as understanding develops","Because the rollout plan changed, the organization has a new stakeholder"],"answer":[2],"why":["A data issue may affect the need or risks; it does not itself become the solution.","The sequence is part of the change strategy; the data issue is a constraint or risk.","Correct: a change strategy can evolve while guiding the same transformation toward the future state.","Stakeholder status depends on the relationship to the change, need, or solution, not a plan revision."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §6.4 Define Change Strategy, pp. 124–131","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1021","domains":[5],"level":1,"tag":"Need","q":"A clinic’s appointment line has a two-week wait, causing patients to miss timely care. In BACCM terms, what is the need?","opts":["The implementation project","The online scheduling application proposed by staff","The reduction in missed appointments expected after implementation","The problem of delayed access to appointments"],"answer":[3],"why":["This is a vehicle for the change, not the underlying need.","This is a possible Solution.","This is an expected Value or outcome.","Correct: Need is the problem or opportunity to be addressed."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §6.1 Analyze Current State, pp. 103–110","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1022","domains":[5],"level":2,"tag":"Need","q":"Which can represent a Need in business analysis?","opts":["An opportunity that could be pursued","A solution component already selected","A constraint requiring attention","A problem that should be solved"],"answer":[0,2,3],"why":["Correct: a need may also be an opportunity.","A selected component is part of a proposed solution.","Correct: a constraint may create or shape a need.","Correct: a need may arise from a problem."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23","multi":true,"sourceSet":"ecba-set-26.html"},{"id":"q1023","domains":[5],"level":3,"tag":"Need","q":"An insurer discovers that customers abandon claims because required forms are difficult to understand. Which statement best identifies the Need?","opts":["Make claim forms easier to understand so customers can complete claims","The claims operations manager who reported the issue","Deploy a mobile application with an embedded form wizard","Increase customer satisfaction by 12 percent"],"answer":[0],"why":["Correct: this states the problem or desired improvement to address.","This is a stakeholder.","This is a possible solution.","This is a desired outcome or measure of value."],"ref":"BABOK Guide v3 §6.1 Analyze Current State and §6.2 Define Future State, printed pp. 103–119","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1024","domains":[5],"level":4,"tag":"Need","q":"A university wants to reduce course registration errors. Which items should be distinguished as the Need versus a possible way of meeting it?","opts":["The registrar is the Need because they requested the work","The number of errors reduced is a possible measure of Value","A redesigned registration workflow is a possible Solution","The registration error problem is the Need"],"answer":[1,2,3],"why":["The registrar is a Stakeholder, not the Need.","Correct: the reduction can measure a benefit or Value.","Correct: the redesigned workflow is one possible Solution.","Correct: the problem to address expresses the Need."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §6.2 Define Future State, pp. 110–119","multi":true,"sourceSet":"ecba-set-26.html"},{"id":"q1025","domains":[5],"level":5,"tag":"Need","q":"A logistics company initially frames its need as “buy route-optimization software.” Interviews reveal the root issue is that dispatchers receive incomplete delivery data. What is the best business analysis response?","opts":["Keep the software purchase as the need because management named it","Reframe the need around the underlying information problem before comparing solutions","Treat the dispatchers’ training as the only possible solution","Record the software vendor as the business objective"],"answer":[1],"why":["A requested product is a proposed solution, not necessarily the underlying need.","Correct: distinguish the underlying problem from a proposed solution so alternatives can be assessed.","Training may be one option but should not be assumed to be the only one.","A vendor is not a business objective."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §6.1 Analyze Current State, pp. 103–110","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1026","domains":[6],"level":1,"tag":"Solution","q":"A city wants to reduce missed waste pickups. Which is a Solution?","opts":["The problem of missed pickups","The value of cleaner streets","A route-planning service that alerts crews to missed collection points","The residents and collection crews affected by the issue"],"answer":[2],"why":["This is the Need.","This is Value.","Correct: a solution is a specific way of satisfying one or more needs in a context.","These are Stakeholders."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §7.5 Define Design Options, pp. 152–157","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1027","domains":[6],"level":2,"tag":"Solution","q":"Which statements describe the BACCM concept Solution?","opts":["It can consist of organizational change, technology, or both","It satisfies one or more needs in a context","It can be evaluated to determine whether it delivers value","It is always a purchased software product"],"answer":[0,1,2],"why":["Correct: solutions may include changes to processes, people, structures, policies, or technology.","Correct: this is central to the BACCM definition.","Correct: solution evaluation examines performance and value delivery.","A solution is not limited to purchased software."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23","multi":true,"sourceSet":"ecba-set-26.html"},{"id":"q1028","domains":[6],"level":3,"tag":"Solution","q":"A hotel’s need is to shorten check-in queues. Which activity is most directly about identifying and describing alternative ways to meet that need?","opts":["Measure Solution Performance","Plan Stakeholder Engagement","Approve Requirements","Define Design Options"],"answer":[3],"why":["Performance measurement evaluates an implemented solution.","Stakeholder engagement plans involvement and communication.","Approval authorizes requirements and designs.","Correct: Define Design Options describes possible approaches for satisfying the need."],"ref":"BABOK Guide v3 §7.5 Define Design Options and §7.6 Analyze Potential Value and Recommend Solution, printed pp. 152–162","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1029","domains":[6],"level":4,"tag":"Solution","q":"A retailer is comparing self-checkout kiosks, additional staffed lanes, and mobile checkout. Which are valid considerations when determining whether an option is an appropriate Solution?","opts":["Whether it is feasible within relevant constraints","Whether it satisfies the identified need","Whether it is the first option proposed","Whether it can deliver value in the retailer’s context"],"answer":[0,1,3],"why":["Correct: feasibility and constraints affect whether an option can work.","Correct: a solution must address one or more needs.","Order of proposal does not establish suitability.","Correct: value is considered for stakeholders in context."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §7.6 Analyze Potential Value and Recommend Solution, pp. 157–162","multi":true,"sourceSet":"ecba-set-26.html"},{"id":"q1030","domains":[6],"level":5,"tag":"Solution","q":"A proposed AI support tool improves response speed but cannot explain decisions required by policy. What is the strongest analysis?","opts":["Assess the option against the need, context constraints, stakeholder value, and alternative designs","Treat policy as a stakeholder and ignore it in option analysis","Change the need to match the tool’s capabilities","Declare it the solution because it improves one performance measure"],"answer":[0],"why":["Correct: suitability depends on satisfying the need and delivering value within context and constraints; compare alternatives.","Policy is contextual constraint or guidance, not a stakeholder.","The need should not be rewritten to fit a favored option.","A single benefit does not establish that an option is suitable."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §§7.5–7.6, printed pp. 152–162","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1031","domains":[7],"level":1,"tag":"Stakeholder","q":"A payroll system change affects employees, payroll staff, and the payroll vendor. In BACCM terms, what makes each a stakeholder?","opts":["Each must approve the business case","Each has a relationship to the change, need, or solution","Each will operate the new system daily","Each receives the same value from the change"],"answer":[1],"why":["Not every stakeholder approves the business case.","Correct: a stakeholder is a group or individual with a relationship to the change, need, or solution.","Some stakeholders may not operate the solution.","Stakeholders may experience different values and impacts."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §3.2 Plan Stakeholder Engagement, pp. 31–36","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1032","domains":[7],"level":2,"tag":"Stakeholder","q":"Which may be stakeholders in a business analysis initiative?","opts":["People who use or support the solution","Only the person who funds the initiative","A regulator with applicable oversight","Groups affected by the change"],"answer":[0,2,3],"why":["Correct: users and support roles have a relationship to the solution.","Funding sponsors are stakeholders, but they are not the only stakeholders.","Correct: regulators may have a relationship through requirements or oversight.","Correct: affected groups are stakeholders in the change."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23","multi":true,"sourceSet":"ecba-set-26.html"},{"id":"q1033","domains":[7],"level":3,"tag":"Stakeholder","q":"A bank is redesigning loan applications. Which stakeholder is most likely to explain how lending rules are interpreted in daily operations?","opts":["A supplier unrelated to the lending workflow","A prospective applicant who has never applied","A loan-processing domain subject matter expert","A project sponsor with no lending responsibilities"],"answer":[2],"why":["An unrelated supplier does not have relevant domain knowledge.","A prospective applicant may describe customer needs but not internal rule interpretation.","Correct: a domain subject matter expert can explain the business rules and operational practice.","A sponsor provides direction but may not know operational details."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36; §4.1 Prepare for Elicitation, pp. 56–61","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1034","domains":[7],"level":4,"tag":"Stakeholder","q":"A hospital introduces electronic medication reconciliation. Which engagement considerations should the analyst account for?","opts":["Only executives qualify as stakeholders because they authorize funding","Some groups may be affected even if they do not use the software directly","Stakeholder influence and level of interest may shape engagement","Different stakeholder groups may have different needs and perspectives"],"answer":[1,2,3],"why":["Stakeholders are not limited to executives.","Correct: patients, compliance roles, and support teams may be affected without directly using the application.","Correct: stakeholder analysis considers characteristics such as influence and interest.","Correct: perspectives differ by role and relationship to the change."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §3.2 Plan Stakeholder Engagement, pp. 31–36","multi":true,"sourceSet":"ecba-set-26.html"},{"id":"q1035","domains":[7],"level":5,"tag":"Stakeholder","q":"A supplier provides a critical data feed, while a regulator sets reporting requirements and customers receive the service. How should the analyst treat these groups?","opts":["Use one identical elicitation approach because all are stakeholders","Treat only customers as stakeholders because they receive value","Ask the supplier to approve regulatory requirements on the regulator’s behalf","Recognize all three as stakeholders and plan engagement suited to their relationships and information needs"],"answer":[3],"why":["Engagement techniques should fit stakeholder roles, availability, and information needs.","Suppliers and regulators are also stakeholders.","The regulator’s authority cannot be delegated to a supplier by assumption.","Correct: each group has a distinct relationship to the change or solution and may need a tailored engagement approach."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement and §4.1 Prepare for Elicitation, printed pp. 31–36, 56–61","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1036","domains":[8],"level":1,"tag":"Value","q":"A new returns process saves customers time and reduces handling costs for the retailer. What is Value in this example?","opts":["The usefulness or benefit experienced by stakeholders in context","The software used to track returned items","The original returns problem","The process change itself"],"answer":[0],"why":["Correct: value is the worth, importance, or usefulness of something to a stakeholder within a context.","This is a Solution component.","This is the Need.","This is the Change."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §8.1 Measure Solution Performance, pp. 166–170","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1037","domains":[8],"level":2,"tag":"Value","q":"Which statements about Value are consistent with the BACCM?","opts":["Value may be tangible or intangible","Value is considered from a stakeholder’s perspective","Value depends on the context in which it is considered","Value is identical for every stakeholder"],"answer":[0,1,2],"why":["Correct: value can include measurable and less tangible benefits.","Correct: value is assessed in relation to stakeholders.","Correct: context influences the worth or usefulness of an outcome.","Stakeholders may perceive value differently."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23","multi":true,"sourceSet":"ecba-set-26.html"},{"id":"q1038","domains":[8],"level":3,"tag":"Value","q":"A delivery service spends more on route planning but reduces late deliveries and customer complaints. Which measure best indicates customer value?","opts":["Number of planning meetings held","Change in late-delivery rate or complaint rate","Total number of requirements documented","Number of analysts assigned"],"answer":[1],"why":["Meeting count measures activity, not customer value.","Correct: this measures outcomes customers experience that relate to the intended benefit.","Documentation volume does not demonstrate value realization.","Staffing count does not show whether the need was met."],"ref":"BABOK Guide v3 §§7.6 and 8.1, printed pp. 157–162, 166–170","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1039","domains":[8],"level":4,"tag":"Value","q":"A self-service portal reduces call-center costs, but older customers report difficulty completing transactions. What should the value analysis recognize?","opts":["Customer accessibility outcomes should be considered with operating savings","Value may differ across stakeholder groups","Cost reduction alone proves that the solution delivers value to all stakeholders","Context can affect how benefits and drawbacks are judged"],"answer":[0,1,3],"why":["Correct: accessibility is an important stakeholder outcome to evaluate.","Correct: the same solution can create different value for different stakeholders.","A benefit to the enterprise does not prove value for all groups.","Correct: context influences the importance and usefulness of outcomes."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §8.2 Analyze Performance Measures, pp. 170–173","multi":true,"sourceSet":"ecba-set-26.html"},{"id":"q1040","domains":[8],"level":5,"tag":"Value","q":"A subscription company’s new billing system meets its technical requirements, yet renewal rates remain unchanged and support calls rise. Which conclusion is best?","opts":["Change the value measures until they show improvement","Recommend immediate retirement without examining the performance gap","Technical conformance alone does not establish realized value; analyze performance and causes before recommending action","The solution must be valuable because it met its requirements"],"answer":[2],"why":["Measures should provide reliable evidence, not be altered to force a favorable result.","Retirement may be considered, but recommendations should follow analysis.","Correct: assess actual outcomes against expected value, investigate causes, and then recommend action.","Meeting requirements does not guarantee that expected value was realized."],"ref":"BABOK Guide v3 §§7.6, 8.2, 8.5, printed pp. 157–162, 170–173, 182–187","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1041","domains":[9],"level":1,"tag":"Context","q":"A tax reporting change is affected by new regulations, legacy software, and a seasonal filing deadline. In BACCM terms, these surrounding circumstances are the:","opts":["Value","Need","Solution","Context"],"answer":[3],"why":["Value is usefulness or worth to stakeholders in context.","The Need is the problem or opportunity addressed.","The Solution is a way to satisfy one or more needs.","Correct: Context includes circumstances that influence, are influenced by, and provide understanding of a change."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §6.1 Analyze Current State, pp. 103–110","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1042","domains":[9],"level":2,"tag":"Context","q":"Which may be part of the Context for a proposed business change?","opts":["Existing capabilities and constraints","The solution recommendation as an isolated artifact","Regulatory requirements","Organizational culture"],"answer":[0,2,3],"why":["Correct: capabilities and constraints influence feasible options.","A recommendation is a decision artifact; context is the circumstances around the change.","Correct: regulations shape requirements and constraints.","Correct: organizational culture can influence a change."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23","multi":true,"sourceSet":"ecba-set-26.html"},{"id":"q1043","domains":[9],"level":3,"tag":"Context","q":"A retailer is planning automated checkout. Why should the analyst examine store layout, staffing practices, customer demographics, and connectivity before recommending a design?","opts":["These contextual factors can affect which solution is feasible and valuable","Context is relevant only after the solution has been implemented","These factors replace the need to identify the business need","Context determines that the first proposed design must be selected"],"answer":[0],"why":["Correct: the surrounding circumstances affect design suitability and expected value.","Context is considered during analysis and planning, not only after implementation.","The need still must be understood.","Context informs comparison; it does not dictate automatic selection of the first option."],"ref":"BABOK Guide v3 §§6.1 and 6.2, printed pp. 103–119","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1044","domains":[9],"level":4,"tag":"Context","q":"A global service redesign must account for local privacy laws, language needs, infrastructure, and support hours. Which statements correctly apply Context?","opts":["One design is automatically suitable everywhere if it meets the global requirement","Different locations may create distinct constraints and stakeholder needs","Local conditions may alter the value stakeholders expect","Context may influence the solution and be affected by the change"],"answer":[1,2,3],"why":["A global requirement does not eliminate local feasibility and compliance differences.","Correct: circumstances and stakeholder needs can vary by location.","Correct: context affects what stakeholders consider useful or valuable.","Correct: change and context influence each other."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §6.1 Analyze Current State, pp. 103–110","multi":true,"sourceSet":"ecba-set-26.html"},{"id":"q1045","domains":[9],"level":5,"tag":"Context","q":"An organization plans a remote-work policy change. A new labor rule is announced during analysis, while managers identify a separate concern about team coordination. How should the analyst interpret these facts?","opts":["Ignore the managers’ concern unless it becomes a formal requirement","Treat both as contextual information that may influence the need, change strategy, solution, and expected value","Treat the new rule as the solution because it is externally imposed","Assume the change is complete because a policy draft exists"],"answer":[1],"why":["The concern may reveal stakeholder impact or a need and should be analyzed.","Correct: context includes internal and external circumstances that influence and are affected by the change.","A regulation shapes constraints; it is not the solution.","A draft policy does not mean the transformation has been implemented or achieved."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §§6.1–6.4, printed pp. 103–131","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1046","domains":[3],"level":1,"tag":"ALL","q":"A delivery team is exploring a poorly understood customer problem and expects to learn from frequent releases. Which approach characteristic is most appropriate to plan for?","opts":["An adaptive approach that uses feedback and adjusts as understanding grows","A hybrid approach that requires every task to be completed sequentially","A predictive approach because the solution involves software","A predictive approach that fixes all scope before elicitation begins"],"answer":[0],"why":["Correct: an adaptive approach suits uncertainty and learning as the change proceeds.","Hybrid may combine approaches, but it does not require every task to be sequential.","The technology itself does not determine the approach.","Fixing all scope up front is not a good fit for a poorly understood problem."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31; Business Analysis Standard v2 §4.2 Approaches, printed pp. 14–15","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1047","domains":[2],"level":1,"tag":"ALL","q":"Which items are established through stakeholder analysis and planning engagement?","opts":["Stakeholder-related risks","Stakeholder characteristics and roles","Appropriate collaboration and communication approaches","The approved design option"],"answer":[0,1,2],"why":["Correct: the engagement approach considers stakeholder risks.","Correct: stakeholder analysis identifies involved stakeholders and analyzes their characteristics.","Correct: the analysis informs collaboration and communication approaches.","Design options are produced in Requirements Analysis and Design Definition."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36; Business Analysis Standard v2 §3 Mindset for Effective Business Analysis, printed pp. 9–12","multi":true,"sourceSet":"ecba-set-27.html"},{"id":"q1048","domains":[3],"level":1,"tag":"ALL","q":"Which governance decision establishes who may authorize a proposed requirements change?","opts":["The stakeholder communication frequency","The decision authority and approval responsibility","The business analysis technique to be used","The information storage location"],"answer":[1],"why":["Communication frequency is part of stakeholder engagement planning.","Correct: governance defines decision makers and approval authority.","Technique selection is part of the Business Analysis Approach.","Storage and access belong to Information Management Approach."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–42; Business Analysis Standard v2 §4 Implementing Business Analysis, printed pp. 13–20","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1049","domains":[3],"level":1,"tag":"ALL","q":"A public agency is setting rules for how analysis records are organized, accessed, and retained. Which are inputs to Plan Business Analysis Information Management?","opts":["Business Analysis Approach","Governance Approach","Requirements (approved)","Stakeholder Engagement Approach"],"answer":[0,1,3],"why":["Correct: the Business Analysis Approach informs how information supports planned BA work.","Correct: governance informs decision, approval, and information control needs.","Approved requirements are not a listed input to this task.","Correct: stakeholder information needs guide access and communication planning."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–47; Business Analysis Standard v2 §4.3 Techniques, printed pp. 15–16","multi":true,"sourceSet":"ecba-set-27.html"},{"id":"q1050","domains":[2],"level":1,"tag":"ALL","q":"What is the purpose of Identify Business Analysis Performance Improvements?","opts":["Measure the value delivered by an implemented solution","Assess the enterprise limitations of a proposed solution","Assess business analysis work and plan process improvements where needed","Approve requirements before implementation"],"answer":[2],"why":["That is Solution Evaluation.","That is Assess Enterprise Limitations.","Correct: the task assesses BA work and plans improvements to processes where required.","That is Approve Requirements."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–51; Business Analysis Standard v2 §3.3 Business Analysis Principles, printed pp. 9–10","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1051","domains":[3],"level":1,"tag":"ALL","q":"A business analyst is scheduling interviews across three warehouse shifts. Which output records the logistics, scope, techniques, and support materials for this elicitation work?","opts":["Stakeholder Engagement Approach","Elicitation Results (unconfirmed)","Business Analysis Information (communicated)","Elicitation Activity Plan"],"answer":[3],"why":["This plans stakeholder relationships across the initiative.","These are findings captured after conducting elicitation.","This describes information communicated to target stakeholders.","Correct: the Elicitation Activity Plan guides each activity and includes logistics, scope, techniques, and supporting materials."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–61; Business Analysis Standard v2 §4 Implementing Business Analysis, printed pp. 13–20","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1052","domains":[2],"level":2,"tag":"ALL","q":"Which are the three common types of elicitation described in BABOK?","opts":["Collaborative, research, and experiments","Predictive, adaptive, and hybrid","Document analysis, prototyping, and process modelling","Interviews, workshops, and observation"],"answer":[0],"why":["Correct: BABOK groups elicitation as collaborative, research, and experiments.","These are approaches to business analysis work.","These are techniques that may be used for elicitation or analysis.","These are techniques, not the three elicitation types."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65; Business Analysis Standard v2 §3 Mindset for Effective Business Analysis, printed pp. 9–12","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1053","domains":[2],"level":2,"tag":"ALL","q":"A project team checks interview notes against the original policy and another confirmed source to resolve a conflicting date. Which technique is especially suited to checking the captured information against source documents?","opts":["Functional Decomposition","Document Analysis","Estimation","Decision Analysis"],"answer":[1],"why":["Functional Decomposition breaks something into component parts.","Correct: Document Analysis compares elicitation results with source information or existing documents.","Estimation forecasts effort, cost, or duration.","Decision Analysis evaluates a decision among alternatives."],"ref":"BABOK Guide v3 §4.3 Confirm Elicitation Results, printed pp. 65–67; Business Analysis Standard v2 §3.6 Get Real Using Examples, printed pp. 10–11","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1054","domains":[3],"level":2,"tag":"ALL","q":"When is business analysis information considered communicated?","opts":["When the information is stored in the requirements repository","When the business analyst has approved the document","When the target stakeholders understand its content and implications","When it has been emailed to every stakeholder"],"answer":[2],"why":["Storage supports information management but does not itself communicate meaning.","Analyst approval alone does not establish stakeholder understanding.","Correct: communication is achieved when target stakeholders understand the content and implications.","Distribution alone does not ensure understanding."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71; Business Analysis Standard v2 §4.4 Understanding Requirements and Designs, printed pp. 16–17","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1055","domains":[2],"level":2,"tag":"ALL","q":"A product team has competing views on service changes. Which facilitation objective best reflects Manage Stakeholder Collaboration?","opts":["Ensure one senior stakeholder’s view is adopted quickly","Prevent stakeholders from revisiting a prior decision","Limit discussion to the delivery team","Encourage stakeholders to work toward a common goal"],"answer":[3],"why":["Collaboration seeks useful participation, not automatic dominance by one person.","Stakeholders may need to revisit information as understanding changes.","Relevant stakeholders may extend beyond the delivery team.","Correct: the task encourages stakeholders to work toward a common goal."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74; Business Analysis Standard v2 §3.6 Stimulate Collaboration and Continuous Improvement, printed pp. 10–11","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1056","domains":[3],"level":2,"tag":"ALL","q":"What does requirements traceability help a team understand when a requirement changes?","opts":["Which related requirements, designs, and solution components may be affected","Which stakeholder should facilitate every elicitation session","Whether the requirement is concise enough to be approved","Whether the solution has realized its expected value"],"answer":[0],"why":["Correct: traceability records relationships and helps analyze the effects of a change.","Facilitation roles are considered in stakeholder engagement and elicitation planning.","Conciseness is not the purpose of traceability.","Value realization is assessed in Solution Evaluation."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–83; Business Analysis Standard v2 §4.4.3 Tracing Requirements and Designs, printed pp. 17–18","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1057","domains":[3],"level":2,"tag":"ALL","q":"Which are listed inputs to Maintain Requirements?","opts":["Requirements","Designs","Information Management Approach","Solution Performance Analysis"],"answer":[0,1],"why":["Correct: requirements are maintained throughout their life cycle.","Correct: designs are also maintained for accuracy and consistency.","This informs how information is managed but is a guideline/tool rather than a listed input.","This is not a listed input to Maintain Requirements."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–86; Business Analysis Standard v2 §4.4 Understanding Requirements and Designs, printed pp. 16–17","multi":true,"sourceSet":"ecba-set-27.html"},{"id":"q1058","domains":[3],"level":3,"tag":"ALL","q":"What does prioritization express for a requirement or design?","opts":["Its consistency with every elicitation result","Its relative importance compared with other requirements or designs","Its traceability to an enterprise objective","Its formal approval for implementation"],"answer":[1],"why":["Consistency and quality are checked in verification and confirmation tasks.","Correct: prioritization ranks requirements or designs by relative importance.","Traceability records relationships but does not express priority.","Approval is handled by Approve Requirements."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–91; Business Analysis Standard v2 §4.4 Understanding Requirements and Designs, printed pp. 16–17","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1059","domains":[3],"level":3,"tag":"ALL","q":"A regulator proposes a new reporting field after requirements were approved. Which output communicates the impact analysis and recommendation about the proposed change?","opts":["Requirements (approved)","Requirements (maintained)","Requirements Change Assessment","Requirements (prioritized)"],"answer":[2],"why":["Approved requirements reflect a decision, not the assessment recommendation.","Maintained requirements reflect updates after decisions are made.","Correct: the Requirements Change Assessment records the impact and recommendation to approve, modify, or deny the change.","Prioritization ranks requirements by importance."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–95; Business Analysis Standard v2 §4.4.3 Tracing Requirements and Designs, printed pp. 17–18","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1060","domains":[3],"level":3,"tag":"ALL","q":"Which items are inputs to Approve Requirements?","opts":["Governance Approach","Elicitation Results (unconfirmed)","Designs (verified)","Requirements (verified)"],"answer":[2,3],"why":["Governance Approach guides authority and process but is not a listed input.","Unconfirmed elicitation results are not ready for approval.","Correct: verified designs are also inputs.","Correct: requirements must be verified before approval."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98; Business Analysis Standard v2 §4.4 Understanding Requirements and Designs, printed pp. 16–17","multi":true,"sourceSet":"ecba-set-27.html"},{"id":"q1061","domains":[1],"level":3,"tag":"ALL","q":"A retailer investigates why customers abandon online orders before deciding what to change. Which are listed inputs to Analyze Current State?","opts":["Needs","Business Analysis Approach","Elicitation Results","Solution Recommendation"],"answer":[0,2],"why":["Correct: needs motivate the current-state analysis.","This guides the work but is not a listed input to this task.","Correct: elicitation results inform understanding of the current state.","A Solution Recommendation is produced later after options are analyzed."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":true,"sourceSet":"ecba-set-27.html"},{"id":"q1062","domains":[1],"level":3,"tag":"ALL","q":"Which is the listed input to Define Future State?","opts":["Current State Description","Elicitation Results (confirmed)","Needs","Business Requirements"],"answer":[3],"why":["Current State Description is a guideline/tool for this task, not its listed input.","Confirmed elicitation results are not the listed input.","Needs motivate analysis but are not the named input in the task diagram.","Correct: Business Requirements are the listed input."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1063","domains":[3],"level":3,"tag":"ALL","q":"A planned system migration could disrupt payroll. Which dimensions should the analyst consider when assessing this risk?","opts":["Time frame in which it may occur","Whether the risk owner prefers the proposed solution","Likelihood that it will occur","Consequences and impact if it occurs"],"answer":[0,2,3],"why":["Correct: the potential time frame is considered.","Preference for a solution is not a risk dimension.","Correct: likelihood is assessed.","Correct: consequences and their impact are analyzed."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–124; Business Analysis Standard v2 §4.2 Approaches, printed pp. 14–15","multi":true,"sourceSet":"ecba-set-27.html"},{"id":"q1064","domains":[3],"level":4,"tag":"ALL","q":"What output records the selected approach for moving from the current state toward the desired future state?","opts":["Change Strategy","Requirements Architecture","Solution Recommendation","Current State Description"],"answer":[0],"why":["Correct: Change Strategy describes the approach to achieving the future state.","This organizes relationships among requirements and designs.","This recommends a design option after evaluating potential value.","This describes present conditions and capabilities."],"ref":"BABOK Guide v3 §6.4 Define Change Strategy, printed pp. 124–131; Business Analysis Standard v2 §4.2 Approaches, printed pp. 14–15","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1065","domains":[3],"level":4,"tag":"ALL","q":"A team needs to show the activities and sequence used to fulfill a customer request. Which technique is most directly suited to modeling that workflow?","opts":["Stakeholder List, Map, or Personas","Process Modelling","Data Modelling","Decision Analysis"],"answer":[1],"why":["Stakeholder List, Map, or Personas identify stakeholders and their characteristics.","Correct: Process Modelling represents organizational steps or activities.","Data Modelling describes data structures and relationships.","Decision Analysis evaluates choices."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–141; Business Analysis Standard v2 §4.4.2 Requirement Classification, printed pp. 17–18","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1066","domains":[3],"level":4,"tag":"ALL","q":"Which quality characteristic means a requirement contains only one element and cannot be usefully subdivided?","opts":["Consistent","Feasible","Atomic","Complete"],"answer":[2],"why":["Consistent means it does not conflict with other requirements.","Feasible means achievable within constraints.","Correct: atomic requirements are indivisible and address one thing.","Complete means sufficient information is present for its intended use."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144; Business Analysis Standard v2 §4.4 Understanding Requirements and Designs, printed pp. 16–17","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1067","domains":[1],"level":4,"tag":"ALL","q":"A proposed claims portal meets its stated requirements, but the sponsor asks whether it will reduce claim-processing delays as intended. Which task addresses alignment with business goals and value?","opts":["Verify Requirements","Maintain Requirements","Approve Requirements","Validate Requirements"],"answer":[3],"why":["Verification checks quality characteristics and usability of requirements and designs.","Maintenance keeps requirements and designs accurate and consistent.","Approval obtains agreement and authorization to proceed.","Correct: validation assesses whether requirements and designs support business goals and deliver value."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–148; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1068","domains":[3],"level":4,"tag":"ALL","q":"What is the purpose of Define Requirements Architecture?","opts":["Ensure requirements collectively support one another to achieve the objectives","Record the order in which requirements will be implemented","Obtain formal authorization for requirements","Measure the performance of an implemented solution"],"answer":[0],"why":["Correct: the task ensures the requirements work together as a cohesive whole supporting objectives.","Sequencing and priority are addressed through planning and prioritization.","That is Approve Requirements.","That is Solution Evaluation."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–152; Business Analysis Standard v2 §4.4 Understanding Requirements and Designs, printed pp. 16–17","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1069","domains":[3],"level":4,"tag":"ALL","q":"A transit agency is weighing fare gates, mobile ticket validation, and onboard inspection to reduce fare evasion. Which task defines and represents these possible solution approaches?","opts":["Analyze Current State","Define Design Options","Define Requirements Architecture","Assess Solution Limitations"],"answer":[1],"why":["This analyzes why change is needed and what it affects.","Correct: Define Design Options identifies possible approaches and represents options to achieve the future state.","This structures requirements and their relationships.","This evaluates internal factors limiting an existing solution."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–157; Business Analysis Standard v2 §4.4 Understanding Requirements and Designs, printed pp. 16–17","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1070","domains":[1],"level":5,"tag":"ALL","q":"Which are inputs to Analyze Potential Value and Recommend Solution?","opts":["Requirements (approved)","Design Options","Solution Recommendation","Potential Value"],"answer":[1,3],"why":["Approved requirements are not listed inputs to this task.","Correct: Design Options are compared to recommend an appropriate solution.","This is an output of the task.","Correct: Potential Value provides a benchmark for evaluating options."],"ref":"BABOK Guide v3 §7.6 Analyze Potential Value and Recommend Solution, printed pp. 157–162; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":true,"sourceSet":"ecba-set-27.html"},{"id":"q1071","domains":[1],"level":5,"tag":"ALL","q":"A hospital tracks medication-reconciliation completion and correction rates after introducing a new workflow. What output captures the measures used to evaluate solution performance?","opts":["Recommended Actions","Solution Performance Analysis","Solution Performance Measures","Enterprise Limitation"],"answer":[2],"why":["These are actions recommended by §8.5.","This is the analysis of collected measures, produced by §8.2.","Correct: this output contains measures that indicate how well the solution performs or could perform.","This describes external enterprise factors limiting value."],"ref":"BABOK Guide v3 §8.1 Measure Solution Performance, printed pp. 166–170; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1072","domains":[2],"level":5,"tag":"ALL","q":"Which output records insights from interpreting collected performance measures and may include recommendations to address gaps?","opts":["Enterprise Limitation","Solution Limitation","Solution Performance Measures","Solution Performance Analysis"],"answer":[3],"why":["This describes limitations external to the solution.","This describes limitations internal to the solution.","These are measures used in analysis, not its output.","Correct: Solution Performance Analysis captures the results and insights from analyzing measures."],"ref":"BABOK Guide v3 §8.2 Analyze Performance Measures, printed pp. 170–173; Business Analysis Standard v2 §3.3 Business Analysis Principles, printed pp. 9–10","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1073","domains":[1],"level":5,"tag":"ALL","q":"A bank reviews a third-party payment service after transaction failures have increased. Which are listed inputs to Assess Solution Limitations?","opts":["Current State Description","Solution Performance Analysis","Implemented Solution (external)","Stakeholder Engagement Approach"],"answer":[1,2],"why":["This is associated with Assess Enterprise Limitations, not a listed input here.","Correct: performance analysis informs the assessment of solution limitations.","Correct: an external implemented solution may be assessed for internal limitations.","This is not a listed input to this task."],"ref":"BABOK Guide v3 §8.3 Assess Solution Limitations, printed pp. 173–177; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":true,"sourceSet":"ecba-set-27.html"},{"id":"q1074","domains":[1],"level":5,"tag":"ALL","q":"Which statement distinguishes an Enterprise Limitation from a Solution Limitation?","opts":["An Enterprise Limitation is a defect within a solution component","The two terms describe the same type of constraint","A Solution Limitation is any policy or operating practice outside the solution","An Enterprise Limitation is external to the solution and restricts value realization"],"answer":[3],"why":["A defect inside a solution is a Solution Limitation.","BABOK distinguishes the two tasks and limitation types.","Policies and practices outside the solution may be Enterprise Limitations.","Correct: §8.4 assesses factors external to the solution that restrict value realization."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":false,"sourceSet":"ecba-set-27.html"},{"id":"q1075","domains":[1],"level":5,"tag":"ALL","q":"After analysis, a service is underperforming because of internal defects and an enterprise process constraint. Which actions may be recommended to increase solution value?","opts":["Approve all requirements without further analysis","Retire the solution where appropriate","Enhance or replace the solution","Adjust the organization to improve value realization"],"answer":[1,2,3],"why":["Recommendations should follow assessment and be tied to value, not automatic approval.","Correct: retirement may be recommended when warranted.","Correct: the recommendation may be to enhance or replace the solution.","Correct: organizational adjustments may improve performance and value."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":true,"sourceSet":"ecba-set-27.html"},{"id":"q1076","domains":[3],"level":1,"tag":"ALL","q":"Which items can be established in a Business Analysis Approach?","opts":["The timing and sequence of business analysis work","The techniques that may be used","The activities and deliverables for the initiative","The final measured performance of the implemented solution"],"answer":[0,1,2],"why":["Correct: it identifies when work happens and its sequence.","Correct: techniques may be identified and adjusted as work progresses.","Correct: the approach identifies the BA activities and expected deliverables.","Final solution performance is assessed after implementation."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31; Business Analysis Standard v2 §4.2 Approaches, printed pp. 14–15","multi":true,"sourceSet":"ecba-set-28.html"},{"id":"q1077","domains":[2],"level":1,"tag":"ALL","q":"A regional bank is changing its lending process. What is the primary output of analyzing stakeholders’ roles, characteristics, and communication needs?","opts":["Stakeholder Engagement Approach","Requirements Architecture","Governance Approach","Information Management Approach"],"answer":[0],"why":["Correct: stakeholder analysis informs the plan for effective engagement.","This organizes requirements and their relationships.","This records decision authority, approvals, and change control.","This describes how BA information is stored and accessed."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36; Business Analysis Standard v2 §3 Mindset for Effective Business Analysis, printed pp. 9–12","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1078","domains":[3],"level":1,"tag":"ALL","q":"Which governance element explains how proposed changes to requirements are reviewed and documented?","opts":["The communication channel for routine updates","A defined change control process","The future-state description","The set of elicitation techniques"],"answer":[1],"why":["Routine communication is part of stakeholder engagement and information communication.","Correct: governance defines the process for proposing, analyzing, deciding on, documenting, and communicating changes.","The future state is defined in Strategy Analysis.","Techniques are selected in the Business Analysis Approach and elicitation planning."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–42; Business Analysis Standard v2 §4 Implementing Business Analysis, printed pp. 13–20","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1079","domains":[3],"level":1,"tag":"ALL","q":"An enterprise wants analysis models to be reusable across initiatives and accessible only to authorized staff. Which considerations belong in the Information Management Approach?","opts":["How information is organized and related","The level of detail captured and characteristics maintained","Which design option stakeholders must approve","How information is stored, accessed, and reused"],"answer":[0,1,3],"why":["Correct: the approach defines how information is organized and relationships are represented.","Correct: it establishes detail and information characteristics to maintain.","Selecting an option is outside information management planning.","Correct: storage, access, and reuse are central information management concerns."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–47; Business Analysis Standard v2 §4.3 Techniques, printed pp. 15–16","multi":true,"sourceSet":"ecba-set-28.html"},{"id":"q1080","domains":[2],"level":1,"tag":"ALL","q":"A team reviews whether its analysis activities produced useful deliverables on time and identifies process changes for the next initiative. Which task does this describe?","opts":["Analyze Performance Measures","Assess Requirements Changes","Identify Business Analysis Performance Improvements","Assess Enterprise Limitations"],"answer":[2],"why":["This analyzes performance measures for a solution.","This evaluates a proposed requirements change.","Correct: the task assesses BA work and plans improvements to BA processes.","This identifies enterprise factors that constrain solution value."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–51; Business Analysis Standard v2 §3.3 Business Analysis Principles, printed pp. 9–10","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1081","domains":[3],"level":1,"tag":"ALL","q":"A facilitator is preparing a workshop. Which contents belong in the Elicitation Activity Plan?","opts":["The selected elicitation techniques","The final approval record for requirements","The activity scope and logistics","Supporting materials and resources"],"answer":[0,2,3],"why":["Correct: the plan identifies selected techniques.","Requirement approval is handled through governance and Approve Requirements.","Correct: scope and logistics are included in the activity plan.","Correct: supporting materials and resources are planned."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–61; Business Analysis Standard v2 §4.3 Techniques, printed pp. 15–16","multi":true,"sourceSet":"ecba-set-28.html"},{"id":"q1082","domains":[2],"level":2,"tag":"ALL","q":"A logistics firm does not know whether a proposed loading-bay layout will reduce truck turnaround time. The analyst arranges a controlled pilot to observe actual results. Which elicitation type is being used?","opts":["Collaborative elicitation","Document analysis","Research","Experiment"],"answer":[3],"why":["Collaborative elicitation draws on direct stakeholder interaction.","Document Analysis is a technique, not the elicitation type described.","Research studies information from sources or materials.","Correct: an experiment tests information that cannot be known without a controlled test."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65; Business Analysis Standard v2 §3 Mindset for Effective Business Analysis, printed pp. 9–12","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1083","domains":[2],"level":2,"tag":"ALL","q":"What is the main reason to confirm elicitation results before using them as a basis for further work?","opts":["Check that captured information is accurate and consistent","Verify that the implemented solution meets its targets","Obtain formal approval to implement the solution","Rank the information by business value"],"answer":[0],"why":["Correct: confirmation identifies errors, omissions, conflicts, and ambiguity before the information is used.","Solution performance is evaluated after implementation.","Formal approval is a separate governance and requirements task.","Prioritization ranks requirements or designs."],"ref":"BABOK Guide v3 §4.3 Confirm Elicitation Results, printed pp. 65–67; Business Analysis Standard v2 §3.6 Get Real Using Examples, printed pp. 10–11","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1084","domains":[3],"level":2,"tag":"ALL","q":"A business analyst sends a process model to operations staff, who misunderstand its effect on their work. What should the analyst conclude?","opts":["The model has become an elicitation result","The information has not yet been effectively communicated to its target stakeholders","The model should be approved without discussion","The information is communicated as soon as it is sent"],"answer":[1],"why":["A model is not automatically an elicitation result because it was sent.","Correct: communication is achieved when target stakeholders understand content and implications.","Approval does not resolve the communication gap.","Sending or publishing alone does not ensure understanding."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71; Business Analysis Standard v2 §4.4 Understanding Requirements and Designs, printed pp. 16–17","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1085","domains":[2],"level":2,"tag":"ALL","q":"Which actions support effective management of stakeholder collaboration?","opts":["Restrict collaboration to stakeholders who approve deliverables","Confirm stakeholder roles as the work progresses","Ensure the appropriate stakeholders participate at the appropriate times","Communicate with stakeholders about the work and its products"],"answer":[1,2,3],"why":["Stakeholders can contribute needs, constraints, and assumptions even if they do not approve deliverables.","Correct: roles are identified and confirmed as the initiative evolves.","Correct: participation should fit the stakeholder’s role and timing.","Correct: communication supports ongoing collaboration."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74; Business Analysis Standard v2 §3.6 Stimulate Collaboration and Continuous Improvement, printed pp. 10–11","multi":true,"sourceSet":"ecba-set-28.html"},{"id":"q1086","domains":[3],"level":2,"tag":"ALL","q":"A developer asks which business requirement a screen-level rule supports. Which capability provides the relationship between requirements at different levels?","opts":["Prioritization","Information management","Traceability","Verification"],"answer":[2],"why":["Prioritization expresses relative importance.","Information management organizes and stores BA information.","Correct: traceability records relationships between requirements and designs at different levels.","Verification checks requirement and design quality."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–83; Business Analysis Standard v2 §4.4.3 Tracing Requirements and Designs, printed pp. 17–18","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1087","domains":[3],"level":2,"tag":"ALL","q":"An analyst searches for enterprise policies that could be reused in a new product. Which technique can help identify reusable business rules?","opts":["Item Tracking","Data Mining","Estimation","Business Rules Analysis"],"answer":[3],"why":["Item Tracking manages issues and actions.","Data Mining searches datasets for patterns and relationships.","Estimation forecasts effort, cost, or duration.","Correct: Business Rules Analysis can reveal similar or reusable rules across an enterprise."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–86; Business Analysis Standard v2 §4.4 Understanding Requirements and Designs, printed pp. 16–17","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1088","domains":[3],"level":3,"tag":"ALL","q":"A release team is ordering requirements while considering benefits, risk, and dependencies. Which factors can legitimately inform prioritization?","opts":["Risk associated with implementing or deferring it","Dependencies among requirements","The value expected from the requirement","The order in which stakeholders submitted them"],"answer":[0,1,2],"why":["Correct: risk may affect priority and sequencing.","Correct: dependencies can constrain delivery order.","Correct: relative value can inform priority.","Submission order alone does not determine relative importance."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–91; Business Analysis Standard v2 §4.4 Understanding Requirements and Designs, printed pp. 16–17","multi":true,"sourceSet":"ecba-set-28.html"},{"id":"q1089","domains":[3],"level":3,"tag":"ALL","q":"Which statement best describes the Requirements Change Assessment?","opts":["It records the impact analysis and recommendation for a proposed change","It is the trace relationship between a requirement and a test","It is the final approval record for the change","It is a complete list of requirements arranged by priority"],"answer":[0],"why":["Correct: the assessment communicates impacts and a recommendation to approve, modify, or deny the proposed change.","Traceability records relationships but is not the assessment itself.","Formal authorization is recorded through approval and governance.","Prioritized requirements are a separate output."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–95; Business Analysis Standard v2 §4.4.3 Tracing Requirements and Designs, printed pp. 17–18","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1090","domains":[3],"level":3,"tag":"ALL","q":"A verified requirement is approved by the authorized stakeholder. What does that approval establish?","opts":["Evidence that the requirement will never change","Agreement and authorization to use the requirement as a basis for further work","Proof that the solution has been implemented successfully","Proof that the requirement will deliver its potential value"],"answer":[1],"why":["Approved requirements may still change through governance.","Correct: approval records agreement and authorizes further work based on the requirement.","Implementation and performance are evaluated later.","Value alignment is evaluated through validation and value analysis."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98; Business Analysis Standard v2 §4.4 Understanding Requirements and Designs, printed pp. 16–17","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1091","domains":[1],"level":3,"tag":"ALL","q":"A chain of pharmacies investigates why prescription pickups are delayed before defining a new service. Which outputs can Analyze Current State produce?","opts":["Current State Description","Business Requirements","Solution Recommendation","Requirements Architecture"],"answer":[0,1],"why":["Correct: the task documents current conditions, capabilities, and context.","Correct: it may express the business need as Business Requirements.","A recommendation follows option analysis.","Requirements Architecture is produced in Requirements Analysis and Design Definition."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":true,"sourceSet":"ecba-set-28.html"},{"id":"q1092","domains":[1],"level":3,"tag":"ALL","q":"A manufacturer is defining the future state for a quality improvement initiative. Which item is central to describing the desired future state?","opts":["A catalog of the current system defects only","A list of elicitation activities already completed","Goals and objectives that indicate what the change should achieve","The approval history of every requirement"],"answer":[2],"why":["Current defects inform current-state analysis but do not define the desired state.","Completed elicitation activities are work history, not future-state objectives.","Correct: future-state definition identifies goals, objectives, and measurable outcomes.","Approval history is governance information."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1093","domains":[3],"level":3,"tag":"ALL","q":"Which description best distinguishes a risk from an issue in a change initiative?","opts":["A risk is always negative; an issue is always positive","A risk is a requirement awaiting approval; an issue is any stakeholder concern","A risk is a future solution component; an issue is an enterprise limitation","A risk is an uncertain event or condition that may affect objectives; an issue is already occurring"],"answer":[3],"why":["Risks may present opportunities as well as threats; issues are not inherently positive.","Neither term is defined by approval status or stakeholder concern alone.","These descriptions confuse risk and issue with other concepts.","Correct: a risk is uncertain and may occur, while an issue is a current condition requiring attention."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–124; Business Analysis Standard v2 §4.2 Approaches, printed pp. 14–15","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1094","domains":[3],"level":4,"tag":"ALL","q":"A utility must replace a billing platform without interrupting monthly invoicing. What should its change strategy define?","opts":["The transition approach for achieving the future state","The measured performance of the final solution","The stakeholder list and communication preferences only","The detailed wording of each stakeholder requirement"],"answer":[0],"why":["Correct: the Change Strategy describes the approach for transitioning from current to future state.","Solution performance is measured after implementation.","Stakeholder engagement is planned separately and does not by itself define the transition.","Requirement wording is developed in analysis."],"ref":"BABOK Guide v3 §6.4 Define Change Strategy, printed pp. 124–131; Business Analysis Standard v2 §4.2 Approaches, printed pp. 14–15","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1095","domains":[3],"level":4,"tag":"ALL","q":"A claims analyst wants to show how an adjuster, customer, and payment service interact over time to complete a claim. Which model is most appropriate?","opts":["Stakeholder Map","Sequence Diagram","Data Model","Business Capability Model"],"answer":[1],"why":["A Stakeholder Map represents stakeholders and their relationships or characteristics.","Correct: Sequence Diagrams show interactions and the order in which they occur.","A Data Model describes data structure and relationships.","A Business Capability Model describes enterprise capabilities."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–141; Business Analysis Standard v2 §4.4.2 Requirement Classification, printed pp. 17–18","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1096","domains":[3],"level":4,"tag":"ALL","q":"Two payment requirements prescribe different rounding rules for the same transaction. Which quality characteristic should verification flag?","opts":["Modifiability","Feasibility","Consistency","Atomicity"],"answer":[2],"why":["Modifiability concerns whether a requirement can be changed while preserving quality.","Feasibility concerns implementation within constraints.","Correct: conflicting requirements are not consistent with one another.","Atomicity concerns whether a requirement addresses one thing."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144; Business Analysis Standard v2 §4.4 Understanding Requirements and Designs, printed pp. 16–17","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1097","domains":[1],"level":4,"tag":"ALL","q":"Which guideline is especially useful for determining whether a requirement supports the intended business outcome?","opts":["Information Management Approach","Governance Approach","Elicitation Activity Plan","Business Objectives"],"answer":[3],"why":["This guides storage, access, and use of BA information.","This guides decisions, approvals, and change control.","This guides a particular elicitation activity.","Correct: Business Objectives help assess alignment with desired outcomes and value."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–148; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1098","domains":[3],"level":4,"tag":"ALL","q":"A team groups models by stakeholder viewpoint and checks that the requirements form a coherent whole. Which deliverable captures the structure and relationships?","opts":["Requirements Architecture","Requirements Change Assessment","Solution Performance Analysis","Business Analysis Approach"],"answer":[0],"why":["Correct: Requirements Architecture represents requirements and their interrelationships, along with relevant context.","This assesses a proposed change.","This analyzes collected solution performance measures.","This defines the method for BA activities."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–152; Business Analysis Standard v2 §4.4 Understanding Requirements and Designs, printed pp. 16–17","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1099","domains":[3],"level":4,"tag":"ALL","q":"What does a design option represent?","opts":["The current-state description of an enterprise","A possible way to satisfy a set of requirements","A set of approved requirements only","The final decision about which solution to implement"],"answer":[1],"why":["That describes current-state analysis.","Correct: each design option represents one possible way to satisfy requirements.","Approved requirements are inputs to subsequent work, not a design option.","The final recommendation is made after comparing potential value."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–157; Business Analysis Standard v2 §4.4 Understanding Requirements and Designs, printed pp. 16–17","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1100","domains":[1],"level":5,"tag":"ALL","q":"A retailer compares three checkout options using expected savings, customer experience, and implementation risk. Which are inputs to the task that recommends an option?","opts":["Requirements (approved)","Solution Recommendation","Design Options","Potential Value"],"answer":[2,3],"why":["Approved requirements are not listed inputs to this task.","This is the task output.","Correct: the design options are evaluated against one another.","Correct: Potential Value provides a benchmark for comparing options."],"ref":"BABOK Guide v3 §7.6 Analyze Potential Value and Recommend Solution, printed pp. 157–162; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":true,"sourceSet":"ecba-set-28.html"},{"id":"q1101","domains":[1],"level":5,"tag":"ALL","q":"What is the purpose of Solution Performance Measures?","opts":["Identify all stakeholders affected by a change","Confirm that each requirement is approved","Provide information about how well a solution performs or could perform","Describe how analysis information is stored"],"answer":[2],"why":["Stakeholders are identified and analyzed in §3.2.","Approval is handled in Requirements Life Cycle Management.","Correct: the measures provide evidence about solution performance and potential performance.","Information storage is planned in §3.4."],"ref":"BABOK Guide v3 §8.1 Measure Solution Performance, printed pp. 166–170; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1102","domains":[2],"level":5,"tag":"ALL","q":"After launch, a service’s completion time improves while error rates increase. Which analysis response is appropriate?","opts":["Approve more requirements before examining the data","Discard the error measure because it conflicts with the desired outcome","Declare success because one measure improved","Interpret the measures against expected value and examine trends and variances"],"answer":[3],"why":["Approval is unrelated to analyzing performance data.","Relevant evidence should not be ignored because it is unfavorable.","One favorable measure does not establish overall performance.","Correct: performance analysis interprets measures in relation to expected value and investigates variances."],"ref":"BABOK Guide v3 §8.2 Analyze Performance Measures, printed pp. 170–173; Business Analysis Standard v2 §3.3 Business Analysis Principles, printed pp. 9–10","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1103","domains":[1],"level":5,"tag":"ALL","q":"What does Assess Solution Limitations investigate?","opts":["Factors external to the solution that restrict value realization","Whether requirements are approved","Factors internal to the solution that restrict full realization of value","Whether stakeholders received communicated information"],"answer":[2],"why":["That is the purpose of Assess Enterprise Limitations.","Approval is covered in §5.5.","Correct: this task identifies internal factors such as defects or constraints that limit solution value.","Communication is addressed in §4.4."],"ref":"BABOK Guide v3 §8.3 Assess Solution Limitations, printed pp. 173–177; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1104","domains":[1],"level":5,"tag":"ALL","q":"A scheduling tool works as designed, but an outdated staffing policy prevents managers from using its recommendations. What should be assessed?","opts":["A Solution Limitation","A traceability gap","A requirements quality issue","An Enterprise Limitation"],"answer":[3],"why":["A Solution Limitation is internal to the solution.","No missing requirement relationship is described.","The scenario does not describe a defective or unclear requirement.","Correct: the policy is external to the solution and restricts value realization."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":false,"sourceSet":"ecba-set-28.html"},{"id":"q1105","domains":[1],"level":5,"tag":"ALL","q":"Which actions may be recommended when analysis shows a solution is not realizing its potential value?","opts":["Replace or retire the solution","Enhance the solution","Change the performance results to match the target","Adjust the organization to support value realization"],"answer":[0,1,3],"why":["Correct: replacement or retirement may be recommended where appropriate.","Correct: enhancement may increase value.","Performance results are evidence and should not be changed to fit a target.","Correct: organizational changes may improve solution performance and value."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187; Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":true,"sourceSet":"ecba-set-28.html"},{"id":"q1106","domains":[3],"level":1,"tag":"ALL","q":"What is the purpose of Plan Business Analysis Approach?","opts":["Define an appropriate method for conducting business analysis activities","Determine how information will be stored and accessed","Assess the potential value of design options","Set the authority for approving requirements"],"answer":[0],"why":["Correct: the task defines an appropriate method for conducting business analysis activities.","Information storage and access are addressed in Plan Business Analysis Information Management.","Potential value is analyzed in Requirements Analysis and Design Definition.","Approval authority is addressed through governance."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31; Business Analysis Standard v2 §4.2 Approaches, printed pp. 14–15","multi":false,"sourceSet":"ecba-set-29.html"},{"id":"q1107","domains":[2],"level":1,"tag":"ALL","q":"A public transit agency is planning a fare-payment change. Which outputs are informed by analyzing stakeholders and their relationships to the change?","opts":["An assessment of stakeholder risks and engagement needs","A plan for stakeholder collaboration and communication","A verified set of solution requirements","A solution performance measure set"],"answer":[0,1],"why":["Correct: stakeholder-related risks and engagement needs inform the approach.","Correct: stakeholder analysis informs suitable collaboration and communication approaches.","Verification occurs in Requirements Analysis and Design Definition.","Performance measures are defined in Solution Evaluation."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36; Business Analysis Standard v2 §3 Mindset for Effective Business Analysis, printed pp. 9–12","multi":true,"sourceSet":"ecba-set-29.html"},{"id":"q1108","domains":[3],"level":1,"tag":"ALL","q":"Which question is answered by a Governance Approach?","opts":["Which solution measure will track customer value?","Who can approve a proposed change to a requirement?","How should a process model be decomposed?","Which technique will elicit user needs?"],"answer":[1],"why":["Performance measures are addressed in Solution Evaluation.","Correct: governance identifies decision makers and approval authority.","Process decomposition is part of modeling and analysis.","Technique selection is part of the Business Analysis Approach and elicitation planning."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–42; Business Analysis Standard v2 §4 Implementing Business Analysis, printed pp. 13–20","multi":false,"sourceSet":"ecba-set-29.html"},{"id":"q1109","domains":[3],"level":1,"tag":"ALL","q":"Which are listed inputs to Plan Business Analysis Information Management?","opts":["Business Analysis Approach","Governance Approach","Stakeholder Engagement Approach","Solution Performance Analysis"],"answer":[0,1,2],"why":["Correct: the Business Analysis Approach informs the information needed to support the work.","Correct: the Governance Approach informs control, approval, and access considerations.","Correct: stakeholder needs inform access and use of information.","Solution Performance Analysis is not a listed input to this planning task."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–47; Business Analysis Standard v2 §4.3 Techniques, printed pp. 15–16","multi":true,"sourceSet":"ecba-set-29.html"},{"id":"q1110","domains":[2],"level":1,"tag":"ALL","q":"Which statement describes a performance improvement identified through this task?","opts":["A change to solution functionality to address a product defect","A revised estimate of project cost","A preventive, corrective, or developmental action to improve future BA work","A new approval authority for a requirement"],"answer":[2],"why":["A solution modification is not a BA process improvement.","Cost estimation is a separate analysis activity.","Correct: the task identifies actions needed to improve business analysis performance and processes.","Governance may define approval authority, but this is not a performance improvement action itself."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–51; Business Analysis Standard v2 §3.3 Business Analysis Principles, printed pp. 9–10","multi":false,"sourceSet":"ecba-set-29.html"},{"id":"q1111","domains":[3],"level":1,"tag":"ALL","q":"A business analyst is preparing a focus group for customers. Which items belong in the Elicitation Activity Plan?","opts":["The completed solution performance analysis","The requirements approval decision","The activity scope and logistics","The selected elicitation techniques"],"answer":[2,3],"why":["Performance analysis occurs in Solution Evaluation.","Approval is part of governance and Requirements Life Cycle Management.","Correct: the plan includes scope and logistics for the activity.","Correct: the plan records the selected techniques and supporting plan details."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–61; Business Analysis Standard v2 §4.3 Techniques, printed pp. 15–16","multi":true,"sourceSet":"ecba-set-29.html"}]);